pub fn p95(samples: &[u64]) -> Option<u64> {
    if samples.is_empty() {
        return None;
    }
    let mut sorted = samples.to_vec();
    sorted.sort_unstable();
    let n = sorted.len();
    let rank = n - n / 20;
    Some(sorted[rank - 1])
}

fn main() {
    assert_eq!(p95(&[1, 2, 3, 100]), Some(100), "case 1");
    assert_eq!(p95(&[]), None, "case 2");
    assert_eq!(p95(&[7]), Some(7), "case 3");
    assert_eq!(
        p95(&(1..=20).collect::<Vec<u64>>()),
        Some(19),
        "case 4"
    );
    assert_eq!(p95(&[9, 1, 9, 0]), Some(9), "case 5");
    println!("worked example passed");
}

